"""Bind this repair's unchanged inputs, exact additions, and generated bytes."""
from __future__ import annotations

import hashlib
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[5]
EVIDENCE = Path(__file__).resolve().parent
SCRATCH = Path('/tmp/cloud-T011-routing-guard-01a15001')


def sha(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def main() -> None:
    entry = json.loads((EVIDENCE / 'entry-snapshot.json').read_text())
    initial = {r['path']: r['sha256'] for r in entry['repository_inputs']}
    paths = [r['path'] for r in json.loads((EVIDENCE / 'spec-revision.json').read_text())['inputs']]
    paths += ['reports/implementation/cloud-orchestration/T-011.md',
              'specs/cloud-orchestration/verification/T-011/quality-cycle-1/regression.log',
              'specs/cloud-orchestration/verification/T-011/native-host-trial-1/acceptance.json',
              'specs/cloud-orchestration/verification/T-011/native-host-trial-1/current-source-binding.json']
    assert initial[paths[8]] == '2956e2e48c00cfcb8b7e5380362ae9df7f6627bfa086ad9b987f869931c765ea'
    for path in paths:
        assert sha(ROOT / path) == initial[path], path
    native = json.loads((ROOT / paths[-1]).read_text())
    for path, expected in native.items():
        assert sha(ROOT / path) == expected, path
    pending = []
    for line in (EVIDENCE / 'mirrors-before.log').read_text().splitlines():
        if line.startswith('pending (left alone): '):
            bundle, path = line.removeprefix('pending (left alone): ').split(' <- ')
            staged = bundle + '/' + path
            if 'human-copy-candidate' in bundle:
                staged += '.candidate'
            if staged in initial:
                assert sha(ROOT / staged) == initial[staged], staged
                pending.append(staged)
    canonical = 'plugins/sdd-quality-loop/references/guard-invariants.json'
    before = json.loads((SCRATCH / 'initial' / canonical).read_text())
    after = json.loads((ROOT / canonical).read_text())
    added = ['plugins/sdd-azure-cloud/scripts/cloud.py', 'plugins/sdd-aws-cloud/scripts/cloud.py',
             'plugins/sdd-azure-cloud/scripts/governed-setup.md', 'plugins/sdd-aws-cloud/scripts/governed-setup.md',
             'plugins/sdd-bootstrap/scripts/cloud-routing.py']
    assert set(after['protected_gate_suffixes']) - set(before['protected_gate_suffixes']) == set(added)
    assert [p for p in after['protected_gate_suffixes'] if p not in added] == before['protected_gate_suffixes']
    for key in before:
        if key != 'protected_gate_suffixes':
            assert before[key] == after[key], key
    sources = [canonical, 'plugins/sdd-quality-loop/scripts/generate-guard-invariants.py',
               *[f'plugins/sdd-quality-loop/scripts/sdd-hook-guard.{ext}' for ext in ('py', 'js', 'ps1')],
               *[str(p.relative_to(ROOT)) for p in (ROOT / 'plugins/sdd-quality-loop/scripts/generated').glob('*guard*') if p.is_file()]]
    (EVIDENCE / 'preservation.json').write_text(json.dumps(dict(
        unchanged_evidence={p: initial[p] for p in paths}, native_source_bindings=len(native),
        unchanged_pending_mirrors=pending, exact_added_members=added,
        stable_guard_sources={p: sha(ROOT / p) for p in sources}), indent=2) + '\n')
    print(f'Preserved {len(paths)} frozen/evidence files, {len(native)} native source bindings, '
          f'{len(pending)} pending guard mirrors; exactly five additions')


if __name__ == '__main__':
    main()
